INSERT INTO reward_point_ledger(
    id, tenant_id, people_id, biz_date, biz_type, biz_ref, seq, points, title,
    is_deleted, gmt_created, gmt_modified, gmt_deleted
) VALUES (
    #{id}, #{tenantId}, #{peopleId}, #{bizDate}, #{bizType}, #{bizRef}, #{seq}, #{points}, #{title},
    #{isDeleted}, #{gmtCreated}, #{gmtModified}, #{gmtDeleted}
)

mapper.select:
SELECT biz_type, biz_ref, SUM(points) AS points, MAX(seq) AS seq, MIN(title) AS title
FROM reward_point_ledger
WHERE people_id = #{peopleId}
  AND biz_date = #{bizDate}
  AND is_deleted = 0
  AND biz_type IN
  #{t}
GROUP BY biz_type, biz_ref

SELECT id, tenant_id, people_id, biz_date, biz_type, biz_ref, seq, points, title, gmt_created
FROM reward_point_ledger
WHERE people_id = #{peopleId}
  AND is_deleted = 0
  AND biz_date >= #{from}
  AND biz_date <= #{to}
ORDER BY biz_date DESC, gmt_created DESC, pk_id DESC
LIMIT #{limit}

SELECT COALESCE(SUM(points), 0)
FROM reward_point_ledger
WHERE people_id = #{peopleId}
  AND is_deleted = 0
  AND biz_date >= #{from}
  AND biz_date <= #{to}

SELECT COUNT(1) FROM (
    SELECT biz_ref
    FROM reward_point_ledger
    WHERE people_id = #{peopleId}
      AND biz_type = #{bizType}
      AND biz_date BETWEEN #{from} AND #{to}
      AND is_deleted = 0
    GROUP BY biz_ref
    HAVING SUM(points) > 0
) x

SELECT COUNT(1) FROM (
    SELECT biz_date
    FROM reward_point_ledger
    WHERE people_id = #{peopleId}
      AND biz_type IN ('PLAN', 'MED', 'VITAL')
      AND biz_date BETWEEN #{from} AND #{to}
      AND is_deleted = 0
    GROUP BY biz_date
    HAVING SUM(points) > 0
) x

