SELECT id, tenant_id, people_id, biz_date, active, full_day, due_count, done_count, freeze_used, streak_after
FROM reward_day
WHERE people_id = #{peopleId}
  AND biz_date BETWEEN #{from} AND #{to}
  AND is_deleted = 0
ORDER BY biz_date ASC

