    #{isDeleted}, #{gmtCreated}, #{gmtModified}, #{gmtDeleted}
)

INSERT INTO reward_kudos(
    id, tenant_id, org_id, people_id, staff_id, kudos_date, message,
    is_deleted, gmt_created, gmt_modified, gmt_deleted
) VALUES (
    #{id}, #{tenantId}, #{orgId}, #{peopleId}, #{staffId}, #{kudosDate}, #{message},
    #{isDeleted}, #{gmtCreated}, #{gmtModified}, #{gmtDeleted}
)
ON DUPLICATE KEY UPDATE
    message = VALUES(message),
    gmt_modified = VALUES(gmt_modified)
